"""panovi サイトのポルトガル語(pt-BR)版・スペイン語(中南米向け)版を英語版から作る。

    python3 tools/panovi_l10n/build.py

★英語版(en/)が**正**。pt/es のページは手で直さず、ここの表を直して作り直す。
  英語版の文が変わると、その文を探す置換が見つからずに止まる(=訳し漏れに気づける)。

作り方(2026-10-27 の en 版の事故を受けた作法):
  - 順序つき置換表。各 old が**ちょうど決めた回数**出てくることを確かめてから置き換える
  - 日本語のコメント(CSS / HTML / JS)は落とす
  - 最後に「日本語の文字が0」を確かめる(言語切替の <a lang="ja">日本語</a> だけは例外)
  - 英語のまま残った文が無いかは check.py が英語版と突き合わせて調べる
"""
import re
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(HERE))
import langs as L  # noqa: E402

PANOVI = HERE.parent.parent / "panovi"
JP = re.compile(r"[぀-ヿ㐀-鿿＀-￯　-〿]")
JA_LINK = re.compile(r'<a [^>]*lang="ja"[^>]*>日本語</a>')

APPSTORE_JP = "https://apps.apple.com/jp/app/id6797261654"
# 国を指定しない形。開いた人の国の App Store に飛ぶ(米国・ブラジル・ウルグアイ・メキシコ向け)
APPSTORE_ANY = "https://apps.apple.com/app/id6797261654"


def T(old, pt, es, n=1):
    return (old, {"pt": pt, "es": es}, n)


def strip_jp_comments(s):
    s = re.sub(r"[ \t]*<!--(?:(?!-->).)*?-->\n?",
               lambda m: "" if JP.search(m.group(0)) else m.group(0), s, flags=re.S)
    s = re.sub(r"[ \t]*/\*(?:(?!\*/).)*?\*/[ \t]*\n?",
               lambda m: "" if JP.search(m.group(0)) else m.group(0), s, flags=re.S)
    s = re.sub(r"^[ \t]*//[^\n]*\n", lambda m: "" if JP.search(m.group(0)) else m.group(0), s, flags=re.M)
    s = re.sub(r"[ \t]*//[^\n]*", lambda m: "" if JP.search(m.group(0)) else m.group(0), s)
    return s


def apply(src, table, lang, label):
    s = src
    for old, new, n in table:
        if isinstance(new, dict):
            new = new[lang]
        got = s.count(old)
        if got != n:
            raise SystemExit(f"[{label}/{lang}] 置換元が {got} 回(期待 {n} 回): {old[:90]!r}")
        s = s.replace(old, new)
    return s


def finish(s, lang, label):
    s = strip_jp_comments(s)
    rest = JP.findall(JA_LINK.sub("", s))
    if rest:
        i = JP.search(JA_LINK.sub("", s)).start()
        ctx = JA_LINK.sub("", s)[max(0, i - 60):i + 60]
        raise SystemExit(f"[{label}/{lang}] 日本語が {len(rest)} 文字残っている: …{ctx}…")
    return s


HTML_LANG = {"pt": "pt-BR", "es": "es"}
DIR = {"pt": "pt", "es": "es"}


# ───────────────────────── トップページ ─────────────────────────
def main_table(lang):
    code = HTML_LANG[lang]
    d = DIR[lang]
    return [
        ('<html lang="en">', f'<html lang="{code}">', 1),
        (L.nav("en"), L.nav(code), 1),
        (L.foot("en"), L.foot(code), 1),
        (APPSTORE_JP, APPSTORE_ANY, 3),
        ("/panovi/viewer/en/guide.html", f"/panovi/viewer/{d}/guide.html", 1),
        ("/panovi/viewer/en/", f"/panovi/viewer/{d}/", 2),
        ("/panovi/en/privacy/", f"/panovi/{d}/privacy/", 1),
        # 見出しの無い章(#match)を指していた空のリンク。pt/es には持ち込まない
        ('      <a href="#match">Whole match</a>\n', "", 1),
        ('<script src="/panovi/viewer.js?v=20261108"></script>', '<script src="/panovi/viewer.js?v=20261108"></script>', 1),
    ] + [x for x in MAIN_TEXT]


