def privacy_table(lang):
    code = HTML_LANG[lang]
    d = DIR[lang]
    return [
        ('<html lang="en">', f'<html lang="{code}">', 1),
        (L.others("privacy", "en"), L.others("privacy", code), 1),
        ('<div class="brand"><a href="/panovi/en/">panovi</a></div>', f'<div class="brand"><a href="/panovi/{d}/">panovi</a></div>', 1),
        ('<a href="https://starclip.app/panovi/en/">About the app</a>',
         f'<a href="https://starclip.app/panovi/{d}/">' + {"pt": "Sobre o app", "es": "Acerca de la app"}[lang] + "</a>", 1),
        ("https://policies.google.com/technologies/partner-sites",
         "https://policies.google.com/technologies/partner-sites?hl=" + {"pt": "pt-BR", "es": "es-419"}[lang], 1),
    ] + PRIVACY_TEXT


