def guide_table(lang):
    code = HTML_LANG[lang]
    d = DIR[lang]
    return [
        ('<html lang="en">', f'<html lang="{code}">', 1),
        (L.others("guide", "en", "\n    "), L.others("guide", code, "\n    "), 1),
        ('<a href="../../en/">About panovi</a>',
         f'<a href="../../{d}/">' + {"pt": "Sobre o panovi", "es": "Acerca de panovi"}[lang] + "</a>", 1),
    ] + GUIDE_TEXT


