JOBS = [
    ("en/index.html", "{d}/index.html", main_table, "main"),
    ("en/privacy/index.html", "{d}/privacy/index.html", privacy_table, "privacy"),
    ("viewer/en/index.html", "viewer/{d}/index.html", viewer_table, "viewer"),
    ("viewer/en/guide.html", "viewer/{d}/guide.html", guide_table, "guide"),
]


def main():
    for src, dst, table, label in JOBS:
        en = (PANOVI / src).read_text(encoding="utf-8")
        for lang in ("pt", "es"):
            out = finish(apply(en, table(lang), lang, label), lang, label)
            path = PANOVI / dst.format(d=DIR[lang])
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(out, encoding="utf-8")
            print("wrote", path.relative_to(PANOVI.parent))


if __name__ == "__main__":
    main()
